class ZuWenigGuthabenException : Exception
{
    public ZuWenigGuthabenException(string nachricht) : base(nachricht)
    {
    }
}

var konto = new Konto();
konto.Einzahlen(50);

try
{
    konto.Abheben(20);
    konto.Abheben(100);
}
catch (ZuWenigGuthabenException ex)
{
    Console.WriteLine("Abgelehnt: " + ex.Message);
}
Console.WriteLine("Kontostand: " + konto.Stand);
// Ausgabe:
// Abgelehnt: Es fehlen 70 Euro
// Kontostand: 30

class Konto
{
    public int Stand { get; private set; }

    public void Einzahlen(int betrag)
    {
        Stand += betrag;
    }

    public void Abheben(int betrag)
    {
        if (betrag > Stand)
        {
            throw new ZuWenigGuthabenException($"Es fehlen {betrag - Stand} Euro");
        }
        Stand -= betrag;
    }
}

class ZuWenigGuthabenException : Exception
{
    public ZuWenigGuthabenException(string nachricht) : base(nachricht)
    {
    }
}

try
{
    throw new UngueltigeNoteException(7);
}
catch (UngueltigeNoteException ex)
{
    Console.WriteLine(ex.Message);
    Console.WriteLine("Wert: " + ex.Note);
}
// Ausgabe:
// Note 7 ist nicht erlaubt
// Wert: 7

class UngueltigeNoteException : Exception
{
    public int Note { get; }

    public UngueltigeNoteException(int note)
        : base($"Note {note} ist nicht erlaubt")
    {
        Note = note;
    }
}

