try
{
    throw new SpielException("Feld besetzt");
}
catch (Exception ex)
{
    Console.WriteLine("Fehler: " + ex.Message);
}

class SpielException : Exception
{
    public SpielException(string m) : base(m) { }
}

try
{
    try
    {
        throw new ZugException(4);
    }
    catch (ZugException ex)
    {
        Console.WriteLine("innen " + ex.Feld);
        throw;
    }
}
catch (ZugException ex)
{
    Console.WriteLine("außen " + (ex.Feld + 1));
}

class ZugException : Exception
{
    public int Feld { get; }
    public ZugException(int feld) { Feld = feld; }
}
